"""Move whole folders (and loose files) to their ladder home (plan Task 10 step 5). IDs and links do not change.

Input: drive-index/filing_plan_<date>.csv (group,source,destination,new_name,files,MB,note). Sources are paths under
99_UNSORTED/From_Desktop; "(loose files)" means each file at its top; group "R root" rows are files at the Drive root
matched by name prefix (text before " ("); group "P path" rows give the exact path from My Drive root of one folder or
file (e.g. `Film Study Course`, `00_Primary_Storage_Drive/01_PROJECTS/_STALLED/X`); paths holding health data are
refused. Dry run by default: resolves every source and destination from the index.
--apply re-reads each item live (parent unchanged, not trashed, not shared), refuses a name already taken at the
destination, moves it with gws, and logs id,status,old_parent,new_parent,old_name to drive-index/filing_log.csv
(undo: move back to old_parent, rename to old_name). Safe to rerun: an item already in its planned place (live) reports skip_done.
Statuses: moved | skip_done | skip_changed | skip_shared | skip_exists | skip_health | error_lookup | error.
Usage: python3 -I file_moves.py drive-index/filing_plan_2026-10-31.csv [--apply]
"""
import argparse, csv, json, re, sqlite3, subprocess, threading
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

OUT = Path.home() / "DEV/drive-tools/drive-index"
FD = "00_Primary_Storage_Drive/99_UNSORTED/From_Desktop"
FOLDER = "application/vnd.google-apps.folder"


def gws(args):
    for _ in range(3):
        r = subprocess.run(["gws", "drive", "files", *args], capture_output=True, text=True)
        try:
            return json.loads(r.stdout)
        except ValueError:
            continue
    return None


def split(path):
    return path.rsplit("/", 1) if "/" in path else ("", path)


assert split("a/b/c") == ["a/b", "c"] and split("x") == ("", "x")   # top-level items have folder ""
def q_esc(s):
    """Drive query string literal: backslash and apostrophe escaped."""
    return s.replace("\\", "\\\\").replace("'", "\\'")


assert q_esc("Coach's \\x") == "Coach\\'s \\\\x"
HEALTH = re.compile(r"(?i)DexaProject|Health_and_Wellness|SpecialRequests|TOS_ES")   # never moved by a plan row
assert HEALTH.search("00_Primary_Storage_Drive/01_PROJECTS/_ACTIVE/2026-03-26_DexaProject") and not HEALTH.search("AI_Context")


def live_path(fid):
    """Path from My Drive root, read live (parents walked up), in the index's form 'a/b/name'; None on any failure."""
    parts, cur = [], fid
    for _ in range(40):
        m = gws(["get", "--params", json.dumps({"fileId": cur, "fields": "name,parents"})])
        if not m or "name" not in m:
            return None
        ps = m.get("parents") or []
        if not ps:                       # reached My Drive itself (not part of index paths)
            return "/".join(reversed(parts))
        if len(ps) != 1:
            return None
        parts.append(m["name"])
        cur = ps[0]
    return None


def health_below(fid):
    """True if any file or folder under fid matches HEALTH, False if none, None if the live scan failed or was too big."""
    todo, scanned = [fid], 0
    while todo:
        cur, token = todo.pop(), None
        while True:
            p = {"q": f"'{cur}' in parents and trashed = false",
                 "fields": "nextPageToken,files(id,name,mimeType,shared)", "pageSize": 1000}
            if token:
                p["pageToken"] = token
            r = gws(["list", "--params", json.dumps(p)])
            if not r or "files" not in r:
                return None
            for f in r["files"]:
                if HEALTH.search(f["name"]) or f.get("shared") is not False:   # shared or unknown: refuse
                    return True
                if f.get("mimeType") == FOLDER:
                    todo.append(f["id"])
            token = r.get("nextPageToken")
            if not token:
                break
        scanned += 1
        if scanned > 3000:               # shortcut: trees over 3,000 folders are refused, not scanned; raise if needed
            return None
    return False


def plan(csv_path):
    """-> (jobs, dests, problems, checks). jobs: (id, parent_id, old_name, dest_path, new_name), new_name '' keeps
    the name. checks: {id: (source_path, is_folder)} for P path rows, verified live in apply()."""
    con = sqlite3.connect(f"file:{OUT / 'drive.sqlite'}?mode=ro", uri=True)
    by_path = {}
    for fid, parent, name, folder, mime in con.execute("select id, parent, name, folder, mime from files"):
        by_path.setdefault((folder, name), []).append((fid, parent, mime))
    jobs, problems, checks = [], [], {}
    for r in csv.DictReader(open(csv_path)):
        dest, new = r["destination"], r["new_name"]
        if dest.startswith("("):
            continue
        if r["group"] == "P path":
            if HEALTH.search(r["source"]) or HEALTH.search(dest) or HEALTH.search(new):
                problems.append(f"{r['source']}: health-data path, move by hand")
                continue
            folder, name = split(r["source"])
            hits = by_path.get((folder, name), [])
            if len(hits) != 1:
                problems.append(f"{r['source']}: {len(hits)} matches")
                continue
            jobs.append((hits[0][0], hits[0][1], name, dest, new))
            checks[hits[0][0]] = (r["source"], hits[0][2] == FOLDER)
        elif r["group"] == "R root":
            pre = r["source"].split(" (")[0]
            hits = [(fid, p, n) for (folder, n), v in by_path.items() if folder == "" and n.startswith(pre)
                    for fid, p, m in v if m != FOLDER]
            want = int(r["files"]) if "copies" not in r["source"] and "versions" not in r["source"] else len(hits)
            if not hits or len(hits) != want:
                problems.append(f"{r['source']}: {len(hits)} matches")
            jobs += [(fid, p, n, dest, "") for fid, p, n in hits]
        elif r["source"] == "(loose files)":
            loose = [(fid, p, n) for (folder, n), v in by_path.items() if folder == FD
                     for fid, p, m in v if m != FOLDER]
            jobs += [(fid, p, n, f"{dest}/{new}", "") for fid, p, n in loose]
        else:
            folder, name = split(f"{FD}/{r['source']}")
            hits = [h for h in by_path.get((folder, name), []) if h[2] == FOLDER]
            if len(hits) != 1:
                problems.append(f"{r['source']}: {len(hits)} folder matches")
                continue
            jobs.append((hits[0][0], hits[0][1], name, dest, new))
    if checks:   # P path plans: one item per path, nothing overlaps, run one move at a time (apply)
        srcs = [s for s, _ in checks.values()]
        if len(checks) != len(jobs):
            problems.append("P path rows cannot share a plan with other row groups")
        full = {}
        for (folder, name), v in by_path.items():     # a "/" inside a Drive name makes a flat path ambiguous
            p = f"{folder}/{name}" if folder else name
            if p in srcs:
                full[p] = full.get(p, 0) + len(v)
        problems += [f"{s}: {full.get(s, 0)} items have this full path" for s in srcs if full.get(s, 0) != 1]
        for s1 in srcs:
            for s2 in srcs:
                if s2.startswith(s1 + "/"):
                    problems.append(f"source {s2} is inside source {s1}: split into two plans")
            for d in {j[3] for j in jobs}:
                if d == s1 or d.startswith(s1 + "/"):
                    problems.append(f"destination {d} is inside moving source {s1}: split into two plans")
        landing = [(j[3], j[4] or j[2]) for j in jobs]
        problems += [f"two items would land as {d}/{n}" for d, n in set(landing) if landing.count((d, n)) > 1]
    need = {"/".join(d.split("/")[:k]) for d in {j[3] for j in jobs} for k in range(1, d.count("/") + 2)}
    nfold = {}                                         # folders per full path, counted across every split
    for (folder, name), v in by_path.items():
        p = f"{folder}/{name}" if folder else name
        if p in need:
            nfold[p] = nfold.get(p, 0) + sum(1 for h in v if h[2] == FOLDER)
    problems += [f"destination path {p}: {n} folders have it" for p, n in sorted(nfold.items()) if n > 1]
    dests = {}
    for d in {j[3] for j in jobs}:
        folder, name = split(d)
        hit = [h for h in by_path.get((folder, name), []) if h[2] == FOLDER]
        if len(hit) > 1:
            problems.append(f"destination {d}: {len(hit)} folders have that path")
        dests[d] = hit[0][0] if len(hit) == 1 else None   # None: created on --apply (parent must exist)
        if checks and dests[d] is None:
            problems.append(f"destination {d}: P path destinations must already exist")
    return jobs, dests, problems, checks


def ensure(path, dests):
    if dests.get(path):
        return dests[path]
    if path == "":                                     # My Drive root: real id, so the parents check below matches
        r = gws(["get", "--params", json.dumps({"fileId": "root", "fields": "id"})])
        if not r or "id" not in r:
            raise SystemExit("cannot read the My Drive root id")
        dests[""] = r["id"]
        return dests[""]
    folder, name = split(path)
    parent = ensure(folder, dests)
    q = f"name = '{q_esc(name)}' and '{parent}' in parents and trashed = false and mimeType = '{FOLDER}'"
    r = gws(["list", "--params", json.dumps({"q": q, "fields": "files(id)"})])
    if not r or "files" not in r:
        raise SystemExit(f"lookup failed for destination {path}")
    if len(r["files"]) > 1:
        raise SystemExit(f"destination {path}: {len(r['files'])} live folders have that name")
    if r["files"]:
        dests[path] = r["files"][0]["id"]
    else:
        c = gws(["create", "--json", json.dumps({"name": name, "mimeType": FOLDER, "parents": [parent]})])
        if not c or "id" not in c:
            raise SystemExit(f"could not create destination {path}")
        dests[path] = c["id"]
    return dests[path]


def apply(jobs, dests, checks):
    log = OUT / "filing_log.csv"
    done = {r[0] for r in csv.reader(open(log)) if len(r) > 1 and r[1] == "moved"} if log.exists() else set()
    for d in sorted(dests):
        ensure(d, dests)
    for d in {j[3] for j in jobs if j[0] in checks}:   # P path destinations: live path must match and be safe
        lp = live_path(dests[d])
        if lp != d or HEALTH.search(lp):
            raise SystemExit(f"destination {d} reads live as {lp!r}: stop")
    f = open(log, "a", newline="")
    w, lock = csv.writer(f), threading.Lock()   # the log is the undo record: one writer at a time

    def one(j):
        fid, parent, old, dest, new = j
        if fid in done and fid not in checks:          # legacy rows: logged once = never moved again
            return "skip_done"
        to = dests[dest]
        m = gws(["get", "--params", json.dumps({"fileId": fid, "fields": "parents,trashed,shared,name"})])
        if m and m.get("parents") == [to] and m.get("name") == (new or old):
            return "skip_done"                         # live state, not the log: already where this plan puts it
        name = new or old
        q = f"name = '{q_esc(name)}' and '{to}' in parents and trashed = false"
        t = gws(["list", "--params", json.dumps({"q": q, "fields": "files(id)"})])
        src = checks.get(fid)
        if not m or m.get("trashed") or m.get("parents") != [parent] or m.get("name") != old:
            status = "skip_changed"
        elif m.get("shared"):
            status = "skip_shared"
        elif not t or "files" not in t:
            status = "error_lookup"                    # never read a failed lookup as "name free"
        elif t["files"]:
            status = "skip_exists"
        elif src and live_path(fid) != src[0]:
            status = "skip_changed"                    # an ancestor moved or was renamed since the index
        elif src and src[1] and health_below(fid) is not False:
            status = "skip_health"                     # a health folder inside, or the scan failed
        else:
            body = {"name": new} if new else {}
            r = gws(["update", "--params", json.dumps({"fileId": fid, "addParents": to, "removeParents": parent,
                     "fields": "parents"}), "--json", json.dumps(body)])
            status = "moved" if r and r.get("parents") == [to] else "error"
        with lock:
            w.writerow([fid, status, parent, to, old]); f.flush()
        return status

    with ThreadPoolExecutor(1 if checks else 8) as ex:   # P path: serial, so live checks cannot race each other
        res = list(ex.map(one, jobs))
    print({s: res.count(s) for s in set(res)}, "->", log)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("plan")
    ap.add_argument("--apply", action="store_true")
    a = ap.parse_args()
    jobs, dests, problems, checks = plan(a.plan)
    missing = sorted(d for d, i in dests.items() if not i)
    print(f"{len(jobs)} moves, {len(dests)} destinations ({len(missing)} to create: {missing})")
    for p in problems:
        print("PROBLEM", p)
    if a.apply:
        if problems:
            raise SystemExit("fix the problems first")
        apply(jobs, dests, checks)

