def same_row(active, name):
    """Other dated _ACTIVE folders for the same board row as `name` (a different date), all pages."""
    p = {"q": f"'{active}' in parents and trashed = false and mimeType = '{fm.FOLDER}' and "
              f"name contains '{fm.q_esc(name[11:])}'", "fields": "nextPageToken,files(name)", "pageSize": 1000}
    out = []
    while True:
        r = fm.gws(["list", "--params", json.dumps(p)])
        if not r or "files" not in r:
            raise SystemExit(f"lookup failed: {name}")
        out += [f["name"] for f in r["files"] if f["name"] != name and f["name"][11:] == name[11:]
                and not fm.HEALTH.search(f["name"])]
        if not r.get("nextPageToken"):
            return out
        p["pageToken"] = r["nextPageToken"]


def check_board(plan):
    """Every planned folder must belong to a row that is active on the board right now; SystemExit otherwise."""
    rows = json.loads(PORTFOLIO.read_text())["projects"]
    active = {r["name"] for r in rows if r.get("status") == "active" and not fm.HEALTH.search(r["name"])}
    bad = [k for k in plan if k[11:] not in active or k[10:11] != "_"]
    if bad:
        raise SystemExit(f"not an active board row now: {bad}")
    unplanned = sorted(active - {k[11:] for k in PLAN})
    if unplanned:
        print("active rows not in PLAN (have a folder already, or add them):", ", ".join(unplanned))


def create(body):
    """One create call, never retried: a lost reply plus a retry would make a twin. A rerun reconciles by name."""
    r = subprocess.run(["gws", "drive", "files", "create", "--json", json.dumps(body), "--params",
                        json.dumps({"fields": "id,shortcutDetails"})], capture_output=True, text=True)
    try:
        return json.loads(r.stdout)
    except ValueError:
        raise SystemExit(f"create reply unreadable for {body['name']}: check _ACTIVE, then rerun (it reuses by name)")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("only", nargs="*")
    a = ap.parse_args()
    con = sqlite3.connect(f"file:{fm.OUT / 'drive.sqlite'}?mode=ro", uri=True)
    active = resolve(con, ACTIVE)
    if set(a.only) - set(PLAN):
        raise SystemExit(f"not in PLAN: {sorted(set(a.only) - set(PLAN))}")
    plan = {k: v for k, v in PLAN.items() if not a.only or k in a.only}
    check_board(plan)
    targets = {t: resolve(con, R + t) for v in plan.values() for t in v}
    if not a.apply:
        for k, v in plan.items():
            print(k, "->", v or "(empty folder)")
        print(f"{len(plan)} folders, {len(targets)} shortcuts: all targets found live. Add --apply to create.")
        return
    logf = open(fm.OUT / "task12_create_log.csv", "a", newline="")
    log = csv.writer(logf)                         # the undo record: flushed after every create
    for name, ts in plan.items():
        others = same_row(active, name)
        if others:
            raise SystemExit(f"{name}: the row already has _ACTIVE folder(s) {others}; use or merge them first")
        have = [h for h in children(active, name) if h["mimeType"] == fm.FOLDER]
        if len(have) > 1:
            raise SystemExit(f"{name}: {len(have)} folders already")
        if have:
            fid = have[0]["id"]
            print("exists ", name)
        else:
            c = create({"name": name, "mimeType": fm.FOLDER, "parents": [active]})
            if not c or "id" not in c:
                raise SystemExit(f"folder create failed: {name}")
            fid = c["id"]
            log.writerow([fid, "folder", name, active, ""]); logf.flush()
            print("created", name)
        for t in ts:
            sname, tid = t.rsplit("/", 1)[1], targets[t]
            ex = children(fid, sname)
            if any(e.get("shortcutDetails", {}).get("targetId") == tid for e in ex):
                print("  exists  shortcut", sname)
                continue
            if ex:
                raise SystemExit(f"  {name}: name {sname} taken by something else")
            c = create({"name": sname, "mimeType": SC, "parents": [fid], "shortcutDetails": {"targetId": tid}})
            if c and "id" in c:
                log.writerow([c["id"], "shortcut", sname, fid, tid]); logf.flush()
            if not c or c.get("shortcutDetails", {}).get("targetId") != tid:
                raise SystemExit(f"  shortcut {sname} failed: {c}")
            print("  created shortcut", sname)


if __name__ == "__main__":
    main()

