import datetime as dt
import json
import tempfile
import unittest
import unittest.mock
from pathlib import Path

import crosswalk


def row(name, **kw):
    base = {"name": name, "lane": "job", "rank": 1, "status": "paused",
            "purpose": "", "next_action": "", "dev_folder": name}
    base.update(kw)
    return base


class TestCrosswalk(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        root = Path(self.tmp.name)
        self.dev = root / "DEV"
        self.drive = root / "Drive"
        for d in ("Alpha", "VALD_Performance", "VALD_New", "Stubby", "_ARCHIVE", "docs"):
            (self.dev / d).mkdir(parents=True)
        for d in ("Alpha", "VALD_Performance", "VALD_New", "Stubby"):
            (self.dev / d / ".git").mkdir()
        (self.dev / "Stubby/docs").mkdir()
        (self.dev / "Stubby/docs/STATUS.md").write_text(
            "# STATUS\n\n## Done\n- Repo brought under git and pushed to erash11 (2026-09-09).\n", encoding="utf-8")
        for d in ("_ACTIVE/2026-01-01_Alpha", "_ACTIVE/2026-02-02_Orphan", "_DONE/Old"):
            (self.drive / "01_PROJECTS" / d).mkdir(parents=True)
        (self.drive / "01_PROJECTS/_ACTIVE/loose.docx").write_text("x", encoding="utf-8")
        self.data = {"meta": {}, "ideas": [], "inbox": [], "projects": [
            row("Alpha", drive_folder="01_PROJECTS/_ACTIVE/2026-01-01_Alpha"),
            row("VALD_Performance"),
            row("Stubby"),
            row("Old", dev_folder="", drive_folder="01_PROJECTS/_DONE/Old", status="done"),
            row("Gone", status="paused"),                       # folder missing
            row("Retired", status="archived"),                  # archived: missing clone is expected
            row("NoDrive", dev_folder="", drive_folder="01_PROJECTS/_ACTIVE/Nope"),
        ]}
        self.recent = lambda p: "2026-10-01"

    def tearDown(self):
        self.tmp.cleanup()

    def run_check(self, **kw):
        kw.setdefault("drive_root", self.drive)
        kw.setdefault("last_commit", self.recent)
        return crosswalk.check(self.data, self.dev, since=dt.date(2026, 9, 12), **kw)

    def kinds(self, result):
        return {(p["kind"], p["name"]) for p in result["problems"]}

    def test_unregistered_dev_folder_is_reported_with_its_likely_family(self):
        result = self.run_check()
        self.assertIn(("unregistered_dev", "VALD_New"), self.kinds(result))
        hint = next(p for p in result["problems"] if p["name"] == "VALD_New")["detail"]
        self.assertIn("VALD_Performance", hint)

    def test_skipped_folders_are_never_reported(self):
        names = {p["name"] for p in self.run_check()["problems"]}
        self.assertNotIn("_ARCHIVE", names)
        self.assertNotIn("docs", names)

    def test_unregistered_drive_project_folder_is_reported_but_loose_files_are_not(self):
        k = self.kinds(self.run_check())
        self.assertIn(("unregistered_drive", "_ACTIVE/2026-02-02_Orphan"), k)
        self.assertFalse(any("loose.docx" in n for _, n in k))
        # Mount still has _DONE/Old; Drive moved it to _ACTIVE (2026-10-31 NCAA case).
        api = {"_ACTIVE": self.API["_ACTIVE"] | {"Old"}, "_DONE": set(), "_STALLED": set()}
        probs = [p for p in self.run_check(drive_api=api)["problems"] if p["kind"] == "missing_drive"]
        self.assertEqual([(p["name"], p["detail"]) for p in probs],
                         [("Old", "01_PROJECTS/_DONE/Old; Drive has it in _ACTIVE")])

    def test_unregistered_drive_folders_come_from_the_api_when_given(self):
        api = {**self.API, "_STALLED": {"New_On_Drive_Only"}}
        k = self.kinds(self.run_check(drive_api=api))
        self.assertIn(("unregistered_drive", "_STALLED/New_On_Drive_Only"), k)
        self.assertIn(("unregistered_drive", "_ACTIVE/2026-02-02_Orphan"), k)

    def test_api_failure_is_reported_and_the_mount_check_still_runs(self):

